import { listLawRecords, getLawRecord, newLawBook, editLawBook, newLawEdition, chooseLawEdition, newLawMemo, editLawMemo, toggleLawFavorite, removeLawRecord, replaceLawRecords } from '../lib/law-store.mjs';
import { activeEdition, parseArticles, searchLaws, exportLawDataset, parseLawDataset } from '../lib/law-core.mjs';
import { escapeHtml as e } from '../lib/sites.mjs';
let entries=[],selectedBook='',query='',favOnly=false,selectedTab='articles',selectedEdition='',visible=60;
export async function refreshLaw(){entries=await listLawRecords();}
export function lawRecords(){return entries;}
function dateNow(){return new Date().toISOString().slice(0,10);}
function saveFile(name,content){const blob=new Blob([content],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const excerpt=(text,n=350)=>text.length>n?text.slice(0,n).trim()+'…':text;
const link=(url,title)=>url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(title)} ↗</a>`:'';
function lawDialog(title,body,formType,recordId='',other=''){
 const old=document.getElementById('law-dialog');if(old?.open)old.close();old?.remove();
 const element=document.createElement('dialog');element.id='law-dialog';element.innerHTML=`<form id="law-form"><h2>${e(title)}</h2><input type="hidden" name="formType" value="${e(formType)}"><input type="hidden" name="recordId" value="${e(recordId)}">${other}${body}<div class="dialog-actions"><button type="button" class="button secondary" data-law-action="close">Отмена</button><button type="submit" class="button primary">Сохранить</button></div></form>`;document.body.append(element);element.showModal();element.addEventListener('close',()=>element.remove(),{once:true});element.querySelector('input:not([type=hidden]),textarea')?.focus();return element;
}
function textField(name,label,value='',extra=''){return `<label class="field">${label}<input name="${name}" value="${e(String(value))}" ${extra}></label>`;}
const lines=(book)=>activeEdition(book).articles.map(a=>`Статья ${a.key}. ${a.title}\n${a.text}`).join('\n\n');
function bookForm(book=null){return `${textField('title','Название нормативного акта',book?.title||'','required maxlength="170"')}${textField('category','Категория (УК, ПК, Конституция и др.)',book?.category||'Закон','required maxlength="90"')}${textField('sourceUrl','Ссылка на официальный источник (HTTPS)',book?.sourceUrl||'','type="url" maxlength="1000"')}${book?'':`${textField('label','Название редакции','Первая редакция','required maxlength="100"')}${textField('effectiveDate','Дата вступления в силу',dateNow(),'required type="date"')}<label class="field">Текст закона<textarea name="articlesText" required rows="13" maxlength="2097152" placeholder="Статья 1. Основания для...\nПолный текст статьи...\n\nСтатья 2. Порядок...\nПолный текст статьи..."></textarea></label><p class="subtle">Каждая статья начинается с «Статья 1. Название». Заголовки и текст образуют отдельные карточки. Изменения можно вносить через новые редакции.</p>`}`;}
function editionForm(book){return `${textField('label','Название новой редакции',`Редакция ${book.editions.length+1}`,'required maxlength="100"')}${textField('effectiveDate','Дата вступления в силу',dateNow(),'required type="date"')}<label class="field">Полный текст новой редакции<textarea name="articlesText" required rows="14" maxlength="2097152">${e(lines(book))}</textarea></label><p class="subtle">Заготовлен текст активной редакции. После сохранения старая редакция останется неизменной, будет доступно сравнение.</p>`;}
function memoForm(memo=null){return `${textField('title','Заголовок памятки',memo?.title||'','required maxlength="150"')}${textField('category','Категория',memo?.category||'Общее','required maxlength="90"')}<label class="field">Памятка<textarea name="body" rows="11" maxlength="16000" required>${e(memo?.body||'')}</textarea></label>`;}
function stats(profileId){const rows=entries.filter(x=>x.profileId===profileId);return {books:rows.filter(x=>x.type==='book'),memos:rows.filter(x=>x.type==='memo'),favorites:rows.filter(x=>x.type==='favorite')};}
function editionDiff(current,previous){const prev=new Map(previous.articles.map(a=>[a.key.toLowerCase(),a]));const curr=new Map(current.articles.map(a=>[a.key.toLowerCase(),a]));const added=current.articles.filter(a=>!prev.has(a.key.toLowerCase())).map(a=>a.key);const deleted=previous.articles.filter(a=>!curr.has(a.key.toLowerCase())).map(a=>a.key);const changed=current.articles.filter(a=>{const old=prev.get(a.key.toLowerCase());return old&&(old.title!==a.title||old.text!==a.text);}).map(a=>a.key);return {added,deleted,changed};}
function selectedBookDisplay(profileId){const book=entries.find(x=>x.id===selectedBook&&x.profileId===profileId&&x.type==='book');return book||null;}
function bookHeader(book){const edition=book.editions.find(ed=>ed.id===(selectedEdition||book.activeEditionId))||activeEdition(book);const isCurrent=edition.id===book.activeEditionId;const index=book.editions.findIndex(ed=>ed.id===edition.id);const previous=index>0?book.editions[index-1]:null;const diff=previous?editionDiff(edition,previous):null;
  return `<section class="card law-book"><div class="row spread"><div><div class="eyebrow">${e(book.category)}</div><h3>${e(book.title)}</h3>${link(book.sourceUrl,'Оригинал документа')}</div><button class="button secondary" data-law-action="back">← Все акты</button></div><div class="row"><button class="button secondary" data-law-action="edit-book" data-id="${e(book.id)}">Реквизиты</button><button class="button primary" data-law-action="new-edition" data-id="${e(book.id)}">Новая редакция</button><button class="button danger" data-law-action="delete" data-id="${e(book.id)}">Удалить</button></div><label class="field">Выбранная редакция<select id="law-edition">${book.editions.map(ed=>`<option value="${e(ed.id)}" ${ed.id===edition.id?'selected':''}>${e(ed.label)} · ${e(ed.effectiveDate)}${ed.id===book.activeEditionId?' · текущая':''}</option>`).join('')}</select></label>${isCurrent?'<p class="subtle">Текущая редакция</p>':`<p class="law-old">Историческая редакция. Не используйте её как действующее законодательство.</p>`}${!isCurrent?`<button class="button secondary" data-law-action="activate-edition" data-id="${e(book.id)}" data-edition="${e(edition.id)}">Сделать текущей</button>`:''}${diff?`<div class="law-diff"><strong>Отличия от предыдущей редакции</strong><p class="subtle">Новые: ${diff.added.length?e(diff.added.join(', ')):'нет'} · Изменённые: ${diff.changed.length?e(diff.changed.join(', ')):'нет'} · Удалённые: ${diff.deleted.length?e(diff.deleted.join(', ')):'нет'}</p></div>`:''}<small class="subtle">В редакции ${edition.articles.length} статей. Изменения создают отдельную неизменяемую версию.</small></section>`;
}
function articleCards(profileId,book){const output=(book?searchLaws(entries,profileId,query,{favoritesOnly:favOnly,editionId:selectedEdition}).filter(row=>row.book.id===book.id):searchLaws(entries,profileId,query,{favoritesOnly:favOnly}));return `<section class="card stack"><div class="row spread"><h3>Статьи (${output.length})</h3>${book?'':'<p class="subtle">Поиск во всех действующих редакциях профиля</p>'}</div>${output.length?output.slice(0,visible).map(row=>`<article class="law-article"><div class="row spread"><div><small class="subtle">${e(row.book.title)} · ${e(row.edition.label)}</small><h4>Статья ${e(row.article.key)}. ${e(row.article.title)}</h4></div><button class="button secondary" data-law-action="favorite" data-id="${e(row.book.id)}" data-key="${e(row.article.key)}" title="Добавить или убрать из избранного" aria-label="${row.favorite?'Убрать из избранного':'Добавить в избранное'}">${row.favorite?'★ Избранное':'☆ Избранное'}</button></div><p class="law-text">${e(row.article.text)}</p><div class="row"><button class="button link" data-law-action="copy-article" data-id="${e(row.book.id)}" data-key="${e(row.article.key)}" data-edition="${e(row.edition.id)}">Копировать статью</button><button class="button link" data-law-action="memo-article" data-id="${e(row.book.id)}" data-key="${e(row.article.key)}" data-edition="${e(row.edition.id)}">Создать памятку</button>${!book?`<button class="button link" data-law-action="open-book" data-id="${e(row.book.id)}">Открыть акт →</button>`:''}</div></article>`).join(''):'<p class="empty">Статьи не найдены. Проверьте поисковый запрос или выбранную редакцию.</p>'}${output.length>visible?'<button class="button secondary" data-law-action="more">Показать ещё</button>':''}</section>`;}
function memoCards(profileId){const memos=stats(profileId).memos.filter(m=>!query||[m.title,m.body,m.category].some(v=>v.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru'))));return `<section class="card stack"><div class="row spread"><h3>Памятки (${memos.length})</h3><button class="button primary" data-law-action="new-memo">+ Памятка</button></div>${memos.length?memos.map(m=>`<article class="law-article"><small class="subtle">${e(m.category)}</small><h4>${e(m.title)}</h4><p class="law-text">${e(m.body)}</p><div class="row"><button class="button secondary" data-law-action="edit-memo" data-id="${e(m.id)}">Изменить</button><button class="button secondary" data-law-action="copy-memo" data-id="${e(m.id)}">Копировать</button><button class="button danger" data-law-action="delete" data-id="${e(m.id)}">Удалить</button></div></article>`).join(''):'<p class="empty">Памяток пока нет.</p>'}</section>`;}
export function lawSection(state){const profileId=state.activeProfileId,{books,memos,favorites}=stats(profileId);let book=selectedBookDisplay(profileId);if(!book){selectedBook='';selectedEdition='';}
return `<div class="stack"><section class="card"><div class="row spread"><div><h3>Law Codex</h3><p class="subtle">Локальное игровое законодательство: данные профиля «${e(state.profiles.find(p=>p.id===profileId)?.name||'')}», без автоматической загрузки из Docossum.</p></div><div class="row"><button class="button primary" data-law-action="new-book">+ Закон</button><button class="button secondary" data-law-action="new-memo">+ Памятка</button></div></div><div class="law-stats"><span>Актов: <b>${books.length}</b></span><span>Памяток: <b>${memos.length}</b></span><span>Избранных: <b>${favorites.length}</b></span></div><div class="row"><button class="button secondary" data-law-action="export">Экспорт JSON</button><label class="button secondary law-import">Импорт JSON<input type="file" id="law-import-file" accept="application/json,.json" hidden></label></div><p class="subtle">Импорт/экспорт переносит только Law Codex и использует ID профилей. Общая резервная копия включает также остальные модули.</p></section><section class="card stack"><div class="row"><button class="button ${selectedTab==='articles'?'primary':'secondary'}" data-law-action="tab" data-tab="articles">Статьи</button><button class="button ${selectedTab==='memos'?'primary':'secondary'}" data-law-action="tab" data-tab="memos">Памятки</button></div><label class="field">Поиск<input id="law-search" type="search" autocomplete="off" placeholder="Номер, название, фраза из статьи или памятки" value="${e(query)}"></label>${selectedTab==='articles'?`<label class="check"><input type="checkbox" id="law-only-fav" ${favOnly?'checked':''}> Только избранные статьи</label>`:''}</section>${selectedTab==='memos'?memoCards(profileId):`${!book?`<section class="card stack"><h3>Нормативные акты</h3>${books.length?books.map(b=>`<div class="law-book-row"><div><strong>${e(b.title)}</strong><p class="subtle">${e(b.category)} · ${b.editions.length} редакц. · ${activeEdition(b).articles.length} статей · ${e(activeEdition(b).effectiveDate)}</p></div><button class="button secondary" data-law-action="open-book" data-id="${e(b.id)}">Открыть</button></div>`).join(''):'<p class="empty">Нормативных актов нет. Нажмите «+ Закон» и вставьте текст со статьями.</p>'}</section>`:bookHeader(book)}${articleCards(profileId,book)}`}</div>`;}
export function setLawQuery(value){query=String(value).slice(0,250);visible=60;}
export function setLawFavOnly(value){favOnly=Boolean(value);visible=60;}
export function setLawEdition(value){selectedEdition=value;visible=60;}
export async function handleLawAction(button,state,render,feedback){const act=button.dataset.lawAction,recordId=button.dataset.id,profileId=state.activeProfileId;
if(act==='close'){document.getElementById('law-dialog')?.close();return;}
if(act==='tab'){selectedTab=button.dataset.tab;selectedBook='';selectedEdition='';render();return;}
if(act==='back'){selectedBook='';selectedEdition='';render();return;}
if(act==='open-book'){selectedBook=recordId;selectedEdition='';visible=60;render();return;}
if(act==='more'){visible+=60;render();return;}
if(act==='new-book'){lawDialog('Новый нормативный акт',bookForm(),'new-book');return;}
if(act==='new-memo'){lawDialog('Новая памятка',memoForm(),'new-memo');return;}
if(act==='edit-book'){const book=await getLawRecord(recordId);if(book.profileId!==profileId)throw Error('Неверный профиль');lawDialog('Изменить реквизиты',bookForm(book),'edit-book',recordId);return;}
if(act==='new-edition'){const book=await getLawRecord(recordId);if(book.profileId!==profileId)throw Error('Неверный профиль');lawDialog('Новая редакция',editionForm(book),'new-edition',recordId);return;}
if(act==='edit-memo'){const m=await getLawRecord(recordId);if(m.profileId!==profileId)throw Error('Неверный профиль');lawDialog('Изменить памятку',memoForm(m),'edit-memo',recordId);return;}
if(act==='memo-article'){const b=await getLawRecord(recordId);if(b.profileId!==profileId)throw Error('Неверный профиль');const article=b.editions.find(ed=>ed.id===button.dataset.edition)?.articles.find(a=>a.key===button.dataset.key);if(!article)throw Error('Статья не найдена');lawDialog('Памятка по статье',memoForm({title:`${b.title} · статья ${article.key}`,body:article.text,category:b.category}),'new-memo','',`<input type="hidden" name="bookId" value="${e(recordId)}"><input type="hidden" name="articleKey" value="${e(article.key)}">`);return;}
if(act==='delete'){const r=await getLawRecord(recordId);if(r.profileId!==profileId)throw Error('Неверный профиль');if(!confirm(`Удалить «${r.title}»${r.type==='book'?' со всеми редакциями, привязанными памятками и избранным':''}?`))return;await removeLawRecord(recordId);if(selectedBook===recordId){selectedBook='';selectedEdition='';}await refreshLaw();render();feedback('Запись удалена');return;}
if(act==='activate-edition'){const b=await getLawRecord(recordId);if(b.profileId!==profileId)throw Error('Неверный профиль');if(!confirm('Сделать выбранную историческую редакцию текущей?'))return;await chooseLawEdition(recordId,button.dataset.edition);selectedEdition='';await refreshLaw();render();feedback('Текущая редакция переключена');return;}
if(act==='favorite'){await toggleLawFavorite(profileId,recordId,button.dataset.key);await refreshLaw();render();feedback('Избранное обновлено');return;}
if(act==='copy-memo'){const m=await getLawRecord(recordId);if(m.profileId!==profileId)throw Error('Неверный профиль');await navigator.clipboard.writeText(`${m.title}\n\n${m.body}`);feedback('Памятка скопирована');return;}
if(act==='copy-article'){const b=await getLawRecord(recordId);if(b.profileId!==profileId)throw Error('Неверный профиль');const ed=b.editions.find(x=>x.id===button.dataset.edition),art=ed?.articles.find(a=>a.key===button.dataset.key);if(!art)throw Error('Статья не найдена');await navigator.clipboard.writeText(`${b.title} (${ed.label})\nСтатья ${art.key}. ${art.title}\n${art.text}\n${b.sourceUrl}`);feedback('Статья скопирована');return;}
if(act==='export'){saveFile(`majestictoolkit-law-${dateNow()}.json`,exportLawDataset(entries,state.profiles.map(p=>p.id)));feedback('Law Codex экспортирован');return;}
}
export async function handleLawSubmit(event,state,render,feedback){const form=event.target;const values=Object.fromEntries(new FormData(form).entries());const kind=values.formType,id=values.recordId,profileId=state.activeProfileId;
if(kind==='new-book'){parseArticles(values.articlesText);const b=await newLawBook(profileId,values);selectedBook=b.id;selectedEdition='';selectedTab='articles';}
else if(kind==='edit-book'){const old=await getLawRecord(id);if(old.profileId!==profileId)throw Error('Неверный профиль');await editLawBook(id,values);}
else if(kind==='new-edition'){parseArticles(values.articlesText);const old=await getLawRecord(id);if(old.profileId!==profileId)throw Error('Неверный профиль');await newLawEdition(id,values);selectedEdition='';}
else if(kind==='new-memo'){await newLawMemo(profileId,values);selectedTab='memos';}
else if(kind==='edit-memo'){const old=await getLawRecord(id);if(old.profileId!==profileId)throw Error('Неверный профиль');await editLawMemo(id,values);}
else throw Error('Неизвестное действие Law Codex');
form.closest('dialog').close();await refreshLaw();render();feedback('Изменения сохранены');
}
export async function importLawFile(file,state,render,feedback){if(file.size>16*1024*1024)throw Error('JSON больше 16 МиБ');const records=parseLawDataset(await file.text(),state.profiles.map(p=>p.id));if(!confirm(`Импортировать ${records.length} записей Law Codex? Существующие законы и памятки будут заменены. Другие модули останутся без изменений.`))return;await replaceLawRecords(records,state.profiles.map(p=>p.id));selectedBook='';selectedEdition='';await refreshLaw();render();feedback('Law Codex импортирован');}
